arguments.file_text:
:root {
  --bg: #0b0d10;
  --bg-elev: #14181d;
  --bg-elev-2: #1c2128;
  --border: #2a313a;
  --border-strong: #3a434f;
  --text: #f1f3f5;
  --text-muted: #aab2bd;
  --text-dim: #7a8290;
  --accent: #ffd166;
  --accent-ink: #161616;
  --danger: #ff6b6b;
  --success: #51cf66;
  --link: #9ecbff;
  --focus: #ffd166;
  --radius: 14px;
  --radius-sm: 8px;
  --shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  --maxw: 1240px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

img, svg { display: block; max-width: 100%; }

a {
  color: var(--link);
  text-decoration-thickness: 1px;
  text-underline-offset: 2px;
}

a:hover { text-decoration: none; }

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  cursor: pointer;
}

/* Skip link */
.skip-link {
  position: absolute;
  left: 8px;
  top: -100px;
  background: var(--accent);
  color: var(--accent-ink);
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  z-index: 100;
  transition: top 0.15s ease;
}
.skip-link:focus { top: 8px; }

/* Layout */
.container {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 24px;
}

/* ===== Header ===== */
.announcement {
  background: var(--bg-elev-2);
  border-bottom: 1px solid var(--border);
  font-size: 0.875rem;
  color: var(--text-muted);
  text-align: center;
  padding: 10px 16px;
}
.announcement strong { color: var(--accent); }

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(11, 13, 16, 0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 14px 24px;
  max-width: var(--maxw);
  margin: 0 auto;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--text);
  text-decoration: none;
  font-weight: 800;
  font-size: 1.15rem;
  letter-spacing: 0.02em;
}
.brand-mark {
  width: 32px; height: 32px;
  border-radius: 8px;
  background: linear-gradient(135deg, var(--accent), #ff8c42);
  color: var(--accent-ink);
  display: grid;
  place-items: center;
  font-weight: 900;
}

.primary-nav { flex: 1; }
.primary-nav ul {
  list-style: none;
  margin: 0; padding: 0;
  display: flex;
  gap: 4px;
}
.primary-nav a {
  display: inline-block;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  text-decoration: none;
  font-weight: 500;
}
.primary-nav a:hover { color: var(--text); background: var(--bg-elev); }

.header-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.icon-btn {
  position: relative;
  width: 40px; height: 40px;
  border-radius: var(--radius-sm);
  display: grid;
  place-items: center;
  color: var(--text);
}
.icon-btn:hover { background: var(--bg-elev); }
.icon-btn svg { width: 20px; height: 20px; }

.cart-badge {
  position: absolute;
  top: 4px; right: 4px;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 9px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 0.7rem;
  font-weight: 800;
  display: grid;
  place-items: center;
  border: 2px solid var(--bg);
}

.menu-toggle { display: none; }

/* ===== Hero ===== */
.hero {
  position: relative;
  overflow: hidden;
  border-bottom: 1px solid var(--border);
  background:
    radial-gradient(1200px 500px at 80% -10%, rgba(255, 209, 102, 0.12), transparent 60%),
    radial-gradient(900px 500px at -10% 110%, rgba(110, 168, 254, 0.10), transparent 60%),
    var(--bg);
}

.hero-inner {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: 56px;
  align-items: center;
  padding: 72px 24px;
  max-width: var(--maxw);
  margin: 0 auto;
}

.hero-eyebrow {
  display: inline-block;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--accent);
  background: rgba(255, 209, 102, 0.12);
  border: 1px solid rgba(255, 209, 102, 0.3);
  padding: 6px 12px;
  border-radius: 999px;
}

.hero h1 {
  font-size: clamp(2.2rem, 4.5vw, 3.6rem);
  line-height: 1.05;
  margin: 18px 0 16px;
  letter-spacing: -0.02em;
  font-weight: 800;
}
.hero h1 em {
  font-style: normal;
  background: linear-gradient(135deg, var(--accent), #ff8c42);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.hero p.lead {
  font-size: 1.1rem;
  color: var(--text-muted);
  max-width: 52ch;
  margin: 0 0 28px;
}

.cta-row {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 13px 22px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  text-decoration: none;
  border: 1px solid transparent;
  transition: transform 0.05s ease, background 0.15s ease;
}
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: var(--accent);
  color: var(--accent-ink);
}
.btn-primary:hover { background: #ffdb85; }
.btn-secondary {
  background: transparent;
  color: var(--text);
  border-color: var(--border-strong);
}
.btn-secondary:hover { background: var(--bg-elev); }

.hero-meta {
  display: flex;
  gap: 28px;
  margin-top: 36px;
  flex-wrap: wrap;
}
.hero-meta div { display: flex; flex-direction: column; }
.hero-meta strong {
  font-size: 1.4rem;
  color: var(--text);
}
.hero-meta span { color: var(--text-dim); font-size: 0.85rem; }

.hero-visual {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: 24px;
  overflow: hidden;
  background: linear-gradient(135deg, #2a2418, #14181d);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
}
.hero-visual::after {
  content: "";
  position: absolute; inset: 0;
  background:
    radial-gradient(70% 60% at 70% 30%, rgba(255, 209, 102, 0.35), transparent 60%),
    radial-gradient(70% 70% at 20% 80%, rgba(110, 168, 254, 0.25), transparent 60%);
}
.hero-tag {
  position: absolute;
  bottom: 20px; left: 20px;
  z-index: 2;
  background: rgba(20, 24, 29, 0.88);
  backdrop-filter: blur(8px);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  padding: 10px 14px;
  font-size: 0.85rem;
  color: var(--text);
}
.hero-tag b { color: var(--accent); }

/* ===== Section primitives ===== */
.section {
  padding: 72px 0;
  border-bottom: 1px solid var(--border);
}

.section-header {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}
.section-header h2 {
  font-size: clamp(1.6rem, 2.6vw, 2.1rem);
  margin: 0 0 6px;
  letter-spacing: -0.01em;
}
.section-header p {
  margin: 0;
  color: var(--text-muted);
  max-width: 60ch;
}
.section-link {
  font-weight: 600;
  text-decoration: none;
  color: var(--accent);
  white-space: nowrap;
}
.section-link:hover { text-decoration: underline; }

/* ===== Categories strip ===== */
.cat-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 14px;
}
.cat-tile {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 18px 12px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text);
  text-decoration: none;
  transition: transform 0.1s ease, border-color 0.15s ease, background 0.15s ease;
}
.cat-tile:hover {
  background: var(--bg-elev-2);
  border-color: var(--border-strong);
  transform: translateY(-2px);
}
.cat-icon {
  width: 44px; height: 44px;
  border-radius: 12px;
  background: linear-gradient(135deg, #2a313a, #1c2128);
  display: grid;
  place-items: center;
  color: var(--accent);
}
.cat-icon svg { width: 22px; height: 22px; }
.cat-tile span { font-size: 0.9rem; font-weight: 600; }
.cat-tile small { color: var(--text-dim); font-size: 0.78rem; }

/* ===== Product grid ===== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.product-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.1s ease, border-color 0.15s ease;
}
.product-card:hover {
  transform: translateY(-3px);
  border-color: var(--border-strong);
}
.product-media {
  position: relative;
  aspect-ratio: 1 / 1;
  background: var(--bg-elev-2);
  overflow: hidden;
}
.product-media::after {
  content: "";
  position: absolute; inset: 0;
  background:
    radial-gradient(120% 80% at 30% 20%, rgba(255,255,255,0.06), transparent 50%);
  pointer-events: none;
}
.product-swatch {
  position: absolute; inset: 0;
  display: grid; place-items: center;
  font-size: 4rem;
  filter: drop-shadow(0 6px 18px rgba(0,0,0,0.5));
}
.product-badge {
  position: absolute;
  top: 12px; left: 12px;
  z-index: 2;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  padding: 4px 8px;
  border-radius: 6px;
}
.product-badge.new { background: #6ea8fe; color: #0b0d10; }
.product-badge.sale { background: var(--danger); color: #fff; }

.wishlist-btn {
  position: absolute;
  top: 10px; right: 10px;
  z-index: 2;
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(11, 13, 16, 0.7);
  backdrop-filter: blur(8px);
  border: 1px solid var(--border);
  display: grid;
  place-items: center;
  color: var(--text);
}
.wishlist-btn:hover { background: rgba(11, 13, 16, 0.95); }
.wishlist-btn[aria-pressed="true"] {
  color: var(--danger);
  border-color: var(--danger);
}
.wishlist-btn svg { width: 18px; height: 18px; }

.product-body {
  padding: 16px 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}
.product-cat {
  font-size: 0.74rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-dim);
  font-weight: 600;
}
.product-name {
  font-size: 1rem;
  font-weight: 700;
  margin: 0;
  line-height: 1.3;
}
.product-name a {
  color: var(--text);
  text-decoration: none;
}
.product-name a:hover { color: var(--accent); }

.product-rating {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.82rem;
  color: var(--text-muted);
}
.stars { color: var(--accent); letter-spacing: 1px; }

.product-foot {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding-top: 8px;
}
.price { font-weight: 800; font-size: 1.1rem; }
.price .was {
  font-weight: 500;
  color: var(--text-dim);
  text-decoration: line-through;
  margin-left: 6px;
  font-size: 0.9rem;
}
.add-btn {
  background: var(--bg-elev-2);
  border: 1px solid var(--border-strong);
  color: var(--text);
  border-radius: 8px;
  padding: 8px 12px;
  font-weight: 600;
  font-size: 0.85rem;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.add-btn:hover { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
.add-btn svg { width: 14px; height: 14px; }

/* ===== Deals ===== */
.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 20px;
}
.deal-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 32px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  position: relative;
  overflow: hidden;
  min-height: 240px;
}
.deal-card.featured {
  background:
    radial-gradient(700px 300px at 100% 0%, rgba(255, 139, 66, 0.18), transparent 60%),
    linear-gradient(135deg, #2a1f12, #1a1410);
  border-color: #4a3722;
}
.deal-eyebrow {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--accent);
  font-weight: 700;
}
.deal-card h3 {
  font-size: 1.6rem;
  margin: 0;
  letter-spacing: -0.01em;
}
.deal-card.featured h3 { font-size: 2rem; }
.deal-card p {
  color: var(--text-muted);
  margin: 0;
  max-width: 50ch;
}

.countdown {
  display: flex;
  gap: 8px;
  margin: 8px 0 4px;
}
.countdown-cell {
  background: rgba(0,0,0,0.4);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  padding: 10px 12px;
  min-width: 60px;
  text-align: center;
}
.countdown-cell strong {
  display: block;
  font-size: 1.4rem;
  font-variant-numeric: tabular-nums;
  font-weight: 800;
  color: var(--text);
}
.countdown-cell span {
  font-size: 0.7rem;
  text-transform: uppercase;
  color: var(--text-dim);
  letter-spacing: 0.1em;
}

.deal-foot {
  margin-top: auto;
  display: flex;
  gap: 12px;
  align-items: center;
  flex-wrap: wrap;
}
.deal-code {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  background: rgba(255, 209, 102, 0.12);
  border: 1px dashed var(--accent);
  color: var(--accent);
  padding: 6px 10px;
  border-radius: 6px;
  font-weight: 700;
}

/* ===== Editorial ===== */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
}
.article-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.1s ease, border-color 0.15s ease;
}
.article-card:hover {
  transform: translateY(-3px);
  border-color: var(--border-strong);
}
.article-media {
  aspect-ratio: 16 / 10;
  position: relative;
  overflow: hidden;
}
.article-media .gradient {
  position: absolute; inset: 0;
}
.article-card:nth-child(1) .gradient { background: linear-gradient(135deg, #3a2a4d, #1a1325); }
.article-card:nth-child(2) .gradient { background: linear-gradient(135deg, #2a3d4d, #131e25); }
.article-card:nth-child(3) .gradient { background: linear-gradient(135deg, #4d3a2a, #251a13); }
.article-media::after {
  content: "";
  position: absolute; inset: 0;
  background: radial-gradient(80% 60% at 70% 30%, rgba(255,255,255,0.1), transparent 60%);
}
.article-cat {
  position: absolute;
  top: 14px; left: 14px;
  z-index: 2;
  background: rgba(11, 13, 16, 0.8);
  backdrop-filter: blur(8px);
  color: var(--accent);
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 5px 10px;
  border-radius: 999px;
  border: 1px solid var(--border);
}
.article-body {
  padding: 20px 22px 22px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}
.article-body h3 {
  margin: 0;
  font-size: 1.2rem;
  line-height: 1.3;
  letter-spacing: -0.01em;
}
.article-body h3 a {
  color: var(--text);
  text-decoration: none;
}
.article-body h3 a:hover { color: var(--accent); }
.article-body p {
  color: var(--text-muted);
  margin: 0;
  font-size: 0.94rem;
}
.article-meta {
  margin-top: auto;
  padding-top: 12px;
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: 0.82rem;
  color: var(--text-dim);
}

/* ===== Newsletter ===== */
.newsletter {
  background:
    radial-gradient(800px 300px at 20% 0%, rgba(255, 209, 102, 0.12), transparent 60%),
    var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 40px;
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 32px;
  align-items: center;
}
.newsletter h2 {
  font-size: 1.8rem;
  margin: 0 0 8px;
  letter-spacing: -0.01em;
}
.newsletter p {
  color: var(--text-muted);
  margin: 0;
  max-width: 50ch;
}
.newsletter-form {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.field-row {
  display: flex;
  gap: 8px;
}
.input {
  flex: 1;
  background: var(--bg);
  border: 1px solid var(--border-strong);
  color: var(--text);
  border-radius: var(--radius-sm);
  padding: 13px 14px;
  font: inherit;
  min-width: 0;
}
.input::placeholder { color: var(--text-dim); }
.input:focus { border-color: var(--accent); outline: none; box-shadow: 0 0 0 3px rgba(255, 209, 102, 0.25); }
.input[aria-invalid="true"] {
  border-color: var(--danger);
  box-shadow: 0 0 0 3px rgba(255, 107, 107, 0.2);
}
.field-help {
  font-size: 0.82rem;
  color: var(--text-dim);
}
.field-error {
  font-size: 0.85rem;
  color: var(--danger);
  font-weight: 600;
}
.form-status {
  font-size: 0.9rem;
  color: var(--success);
  font-weight: 600;
}

/* ===== Footer ===== */
.site-footer {
  background: #07090b;
  color: var(--text-muted);
  padding: 56px 0 24px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(4, 1fr);
  gap: 32px;
  padding-bottom: 32px;
  border-bottom: 1px solid var(--border);
}
.footer-grid h4 {
  color: var(--text);
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin: 0 0 14px;
}
.footer-grid ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.footer-grid a {
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.92rem;
}
.footer-grid a:hover { color: var(--text); text-decoration: underline; }
.footer-brand p { font-size: 0.92rem; max-width: 36ch; margin: 12px 0 16px; }
.socials {
  display: flex;
  gap: 8px;
}
.socials a {
  width: 38px; height: 38px;
  border-radius: 8px;
  background: var(--bg-elev);
  display: grid;
  place-items: center;
  color: var(--text);
}
.socials a:hover { background: var(--bg-elev-2); }
.socials svg { width: 18px; height: 18px; }

.footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding-top: 20px;
  font-size: 0.85rem;
  color: var(--text-dim);
  flex-wrap: wrap;
}

/* ===== Live region (visually hidden) ===== */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ===== Reduced motion ===== */
@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}

/* ===== Forced colors ===== */
@media (forced-colors: active) {
  .btn, .add-btn, .icon-btn, .cat-tile, .product-card, .article-card, .deal-card, .input {
    border: 1px solid ButtonBorder;
  }
  .btn-primary, .add-btn:hover { background: ButtonText; color: ButtonFace; }
  :focus-visible { outline: 3px solid Highlight; }
  .product-badge, .cart-badge, .deal-code { border: 1px solid CanvasText; }
}

/* ===== Reflow ===== */
@media (max-width: 1080px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .cat-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
  .footer-brand { grid-column: 1 / -1; }
}
@media (max-width: 880px) {
  .hero-inner { grid-template-columns: 1fr; padding: 48px 24px; gap: 32px; }
  .hero-visual { aspect-ratio: 16/11; }
  .deals-grid { grid-template-columns: 1fr; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .newsletter { grid-template-columns: 1fr; padding: 32px; }
  .primary-nav { display: none; }
  .primary-nav.open {
    display: block;
    position: absolute;
    top: 100%; left: 0; right: 0;
    background: var(--bg-elev);
    border-bottom: 1px solid var(--border);
    padding: 8px;
  }
  .primary-nav.open ul { flex-direction: column; }
  .menu-toggle { display: grid; }
  .site-header { position: relative; }
}
@media (max-width: 620px) {
  .container { padding: 0 16px; }
  .header-inner { padding: 12px 16px; }
  .section { padding: 48px 0; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 14px; }
  .cat-grid { grid-template-columns: repeat(2, 1fr); }
  .editorial-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .footer-brand { grid-column: 1 / -1; }
  .hero h1 { font-size: 2rem; }
  .field-row { flex-direction: column; }
}

