  const [error, setError] = useState("");
  const [status, setStatus] = useState("");
  const inputRef = useRef(null);

  const submit = (e) => {
    e.preventDefault();
    const v = email.trim();
    const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
    if (!valid) {
      setError("Enter a valid email address, e.g. you@example.com.");
      setStatus("");
      inputRef.current?.focus();
      return;
