function Countdown({ deadline }) {
  const calc = useCallback(() => {
    const ms = Math.max(0, deadline - Date.now());
    const d = Math.floor(ms / 86400000);
    const hh = Math.floor((ms % 86400000) / 3600000);
    const mm = Math.floor((ms % 3600000) / 60000);
    const ss = Math.floor((ms % 60000) / 1000);
    return { d, hh, mm, ss };
  }, [deadline]);

  const [t, setT] = useState(calc);
  useEffect(() => {
    const id = setInterval(() => setT(calc()), 1000);
    return () => clearInterval(id);
  }, [calc]);

  const pad = (n) => String(n).padStart(2, "0");
  const label = `Offer ends in ${t.d} days, ${t.hh} hours, ${t.mm} minutes, ${t.ss} seconds`;

  return h("div", { className: "countdown", role: "timer", "aria-live": "off", "aria-label": label },
    [["Days", t.d], ["Hours", pad(t.hh)], ["Mins", pad(t.mm)], ["Secs", pad(t.ss)]].map(([l, v]) =>
      h("div", { className: "countdown-cell", key: l, "aria-hidden": "true" },
        h("strong", null, v),
        h("span", null, l)
      )
    )
  );
}

