function Newsletter() {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [status, setStatus] = useState("");
  const inputRef = useRef(null);

  const submit = (e) => {
    e.preventDefault();
    const v = email.trim();
    const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
    if (!valid) {
      setError("Enter a valid email address, e.g. you@example.com.");
      setStatus("");
      inputRef.current?.focus();
      return;
    }
    setError("");
    setStatus(`Thanks — we've added ${v} to the list.`);
    setEmail("");
  };

  return h("section", { className: "section", "aria-labelledby": "news-title" },
    h("div", { className: "container" },
      h("div", { className: "newsletter" },
        h("div", null,
          h("h2", { id: "news-title" }, "Slow updates, no spam"),
          h("p", null, "One considered email a month: new drops, journal pieces, and the occasional member offer.")
        ),
        h("form", { className: "newsletter-form", onSubmit: submit, noValidate: true, "aria-describedby": "news-help" },
          h("label", { htmlFor: "news-email", className: "sr-only" }, "Email address (required)"),
          h("div", { className: "field-row" },
            h("input", {
              id: "news-email",
              ref: inputRef,
              type: "email",
              className: "input",
              placeholder: "you@example.com",
              required: true,
              "aria-required": "true",
              "aria-invalid": error ? "true" : "false",
              "aria-describedby": error ? "news-error news-help" : "news-help",
              value: email,
              onChange: (e) => setEmail(e.target.value),
              autoComplete: "email"
            }),
            h("button", { type: "submit", className: "btn btn-primary" }, "Subscribe")
          ),
          error
            ? h("div", { id: "news-error", className: "field-error", role: "alert" }, error)
            : h("div", { id: "news-help", className: "field-help" }, "Required. We'll never share your address."),
          h("div", { className: "form-status", role: "status", "aria-live": "polite" }, status)
        )
      )
    )
  );
}

