function App() {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState([]);
  const [menuOpen, setMenuOpen] = useState(false);
  const [announce, setAnnounce] = useState("");

  const addToCart = (p) => {
    setCart((c) => [...c, p.id]);
    setAnnounce(`${p.name} added to cart.`);
  };
  const toggleWish = (id) => {
    setWishlist((w) => w.includes(id) ? w.filter((x) => x !== id) : [...w, id]);
  };

  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") setMenuOpen(false); };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, []);

  return h(React.Fragment, null,
    h("a", { href: "#main", className: "skip-link" }, "Skip to main content"),
    h(Announcement),
    h(Header, { cartCount: cart.length, onMenuToggle: () => setMenuOpen((v) => !v), menuOpen }),
    h("main", { id: "main" },
      h(Hero),
      h(Categories),
      h(FeaturedProducts, { onAddToCart: addToCart, wishlist, onToggleWish: toggleWish }),
      h(Deals),
      h(Editorial),
      h(Newsletter)
    ),
    h(Footer),
    h("div", { role: "status", "aria-live": "polite", className: "sr-only" }, announce)
  );
}

